import csv,sys,numpy as np
rows=list(csv.DictReader(open("/scr/wurgaft/auto-psych/agent_trees/45bd45c333332e1a/repo/_runs/cell_1/experiment2/model_loop/responses.csv")))
y=np.array([int(r["rating"]) for r in rows]); p=np.load(sys.argv[1])
bins=[0,.02,.05,.1,.2,.3,.4,.5,.6,.7,.8,.9,.95,.98,1.0001]
for a,b in zip(bins[:-1],bins[1:]):
    s=(p>=a)&(p<b)
    if s.sum(): print(f"[{a:.2f},{b:.2f}) n={s.sum():4d} pred={p[s].mean():.3f} obs={y[s].mean():.3f}")
# number of examples / is target an example
ns=np.array([len(r["number_set"].split(",")) for r in rows]); ex=np.array([r["target"] in r["number_set"].split(",") for r in rows])
for k in range(1,5):
  for e in [0,1]:
    s=(ns==k)&(ex==e)
    if s.sum(): print(k,e,s.sum(),p[s].mean().round(3),y[s].mean().round(3))
ti=np.array([int(r["trial_index"]) for r in rows])
for q in np.array_split(np.argsort(ti),5): print("trial", ti[q].min(),ti[q].max(), p[q].mean().round(3), y[q].mean().round(3))
EOF
